import {TYPES,EVENTS,ACTIONS,initial,neighbors,nearWater,local,metrics,allowed,apply,advance,score,tileFacts,validSave,migrateSave} from './engine.mjs';
import {flowFor} from './flow.mjs';
import {PRACTICES,groupFor,fullSPD} from './practices.mjs';
import {sceneHTML,sceneSpec,impactReport,serviceCards,ACTION_FEEDBACK} from './visual.mjs';
const $=id=>document.getElementById(id),saveKey='paisagem-viva-manejo-v2';let state=initial(),selected=null,toastTimer,activeGroup='soil',latestChange=null,showConnections=false,inspectReady=false;
try{const saved=JSON.parse(localStorage.getItem(saveKey));const upgraded=migrateSave(saved);if(upgraded)state=upgraded;}catch{}
const idName=id=>String.fromCharCode(65+Math.floor(id/3))+(id%3+1),photoStyle=type=>`background-position:${TYPES[type].atlas%3*50}% ${Math.floor(TYPES[type].atlas/3)*100}%;`,round=n=>Math.round(n);
function save(){try{localStorage.setItem(saveKey,JSON.stringify(state));}catch{}}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function modal(html,wide=false){$('modal').classList.toggle('modal-wide',wide);$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();$('modal').scrollTop=0;}
const closeModal=()=>$('modal').close(),closeFocus=()=>$('focus').close();$('close-modal').onclick=closeModal;$('close-focus').onclick=closeFocus;
for(const d of [$('modal'),$('focus')])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
const practiceFlags=[['cover','Cobertura do solo'],['noTill','Plantio direto'],['cropRotation','Rotação de culturas'],['compost','Composto orgânico'],['bio','Faixas floridas'],['bioGrowth','Bioinsumo de crescimento'],['microbial','Bioinseticida'],['mip','Manejo integrado'],['fertilizer','Adubação mineral'],['irrigation','Gotejamento']];
function appliedLabels(t){return practiceFlags.filter(([k])=>t[k]).map(([,label])=>label);}
function status(t){const n=appliedLabels(t).length;if(fullSPD(t))return 'Sistema de plantio direto';if(n>1)return `${n} manejos combinados`;if(t.toxic)return 'Inseticida ativo';if(n)return appliedLabels(t)[0];if(t.type==='forest'&&t.maturity<3)return 'Vegetação em recuperação';if(t.type==='silvo'&&t.maturity<3)return 'Árvores em implantação';if(t.type==='agro'&&t.maturity<3)return 'Sistema em implantação';if(t.rotation)return 'Descanso do pasto';if(t.nursery)return 'Refúgio pesqueiro';if(t.intensiveFish)return 'Captura ampliada';if(t.gather)return 'Colheita organizada';if(t.trail)return 'Visitação comunitária';if(t.type==='village'&&state.sanitation)return 'Efluentes tratados';return '';}
function render(){const e=EVENTS[Math.min(state.round,5)],flow=flowFor(state);$('game-main').dataset.phase=flow.phase;$('game-main').classList.toggle('inspect-ready',inspectReady);$('next-title').textContent=flow.title;$('next-instruction').textContent=flow.instruction;$('current-step').textContent=flow.phase==='choose'?'AGORA · ESCOLHA UMA PAISAGEM':flow.phase==='advance'?'ESCOLHAS FEITAS · AVANCE O TEMPO':'PARTIDA CONCLUÍDA';$('cycle-label').textContent=state.done?'MANEJO CONCLUÍDO':`CICLO ${state.round+1} DE 6`;$('cycle-name').textContent=state.done?'O que ficou para a comunidade?':e.season;$('budget').textContent=state.budget;$('work').textContent=state.done?'0':state.actions;$('work-label').textContent=state.actions===1?'escolha disponível':'escolhas disponíveis';$('decision-counter').hidden=!flow.canPick;$('next-action').hidden=flow.canPick;$('choose-cue').hidden=!flow.canPick;$('advance').innerHTML=`${flow.button||'Avançar o ciclo'} <span>→</span>`;$('inspect-map').textContent=inspectReady?'Recolher a paisagem':'Ver a paisagem';$('end-early').hidden=state.done;$('condition').textContent=e.season;$('weather').textContent=state.done?'Confira o balanço final para comparar as escolhas.':e.description;
 $('map').innerHTML=state.tiles.map(t=>`<button class="tile" data-tile="${t.id}" data-type="${t.type}" ${flow.canPick?'':'disabled'} aria-label="Escolher ${TYPES[t.type].name}, setor ${idName(t.id)}"><span class="scene-art">${sceneHTML(state,t.id,{compact:true})}</span><span class="tile-id">${idName(t.id)}</span>${status(t)?`<span class="tile-note">${status(t)}</span>`:''}<span class="tile-label">${TYPES[t.type].name}</span>${flow.canPick?'<span class="tile-pick">Escolher <span aria-hidden="true">→</span></span>':''}</button>`).join('');document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>openSector(Number(b.dataset.tile)));renderTerritoryEffect();
 const h=state.history.at(-1),l=state.log.at(-1);$('last-note').textContent=l&&(!h||l.round>h.round)?`${l.name}, setor ${idName(l.tile)}.`:h?h.notes[0]:'';
}
$('inspect-map').onclick=()=>{inspectReady=!inspectReady;render();};
$('end-early').onclick=()=>{$('advance').click();};
function sectorShell(content){$('focus').classList.remove('change-mode');const t=state.tiles[selected],tags=appliedLabels(t);$('focus-content').innerHTML=`<div class="focus-grid"><section class="focus-land"><div class="eyebrow">SETOR ${idName(selected)}${nearWater(state,selected)&&t.type!=='wetland'?' · MARGEM DA ÁGUA':''}</div><h2>${TYPES[t.type].name}</h2><div class="focus-photo">${sceneHTML(state,selected)}<div class="photo-caption">${t.type==='crop'&&t.cropRotation?'Abóbora e outras espécies se alternam na rotação de culturas.':TYPES[t.type].description}</div></div><div class="facts"><h3>O que existe aqui</h3>${tileFacts(state,selected).slice(0,3).map(f=>`<p>${f}</p>`).join('')}</div>${tags.length?`<div class="active-practices"><h3>Manejos em uso</h3><div>${tags.map(x=>`<span>${x}</span>`).join('')}</div></div>`:''}</section><section class="focus-work">${content}</section></div>`;}
const changes=new Set(['to_crop','to_pasture','agro','restore','rewet']);
function option(a){const available=allowed({...state,done:false},selected,a);return `<button class="option" data-choice="${a.id}"><span><strong>${a.name}</strong><small>${a.summary}</small></span><span class="option-end">${available?(a.cost?`${a.cost} recursos`:'Sem custo'):(a.id==='timber'?'Aguardar reposição':'Em uso')}<br>→</span></button>`;}
function openSector(id){selected=id;activeGroup=['crop','agro'].includes(state.tiles[id].type)?'soil':'use';showOptions();if(!$('focus').open)$('focus').showModal();$('focus').scrollTop=0;}
function showOptions(){const t=state.tiles[selected],agricultural=['crop','agro'].includes(t.type),options=ACTIONS.filter(a=>a.types.includes(t.type)&&(!a.river||nearWater(state,selected))),groups=agricultural?[['soil','Solo e água'],['life','Vida e controle'],['use','Uso do setor']]:[['use','Manejar'],['transform','Transformar']];if(!groups.some(([g])=>g===activeGroup))activeGroup='use';const filter=a=>agricultural?groupFor(a)===activeGroup:activeGroup==='transform'?changes.has(a.id):!changes.has(a.id);const order=['cover','notill','crop_rotation','compost','fertilizer','drip','biocontrol','bio_growth','microbial','mip','spray'];const shown=options.filter(filter).sort((a,b)=>(order.includes(a.id)?order.indexOf(a.id):99)-(order.includes(b.id)?order.indexOf(b.id):99));sectorShell(`<div class="eyebrow">PASSO 2 · ESCOLHA UM MANEJO</div><h3>Como manejar este setor?</h3><p class="focus-intro">${state.done?'A partida terminou. Você pode consultar os planos para discutir outras estratégias.':state.actions?'Clique em um manejo para ver seus ganhos e cuidados.':'As escolhas terminaram. Agora avance o ciclo.'}</p><div class="practice-tabs" role="tablist" aria-label="Tipos de manejo">${groups.map(([g,label])=>`<button role="tab" data-group="${g}" aria-selected="${g===activeGroup}">${label}</button>`).join('')}</div><div class="options options-scroll">${shown.map(option).join('')||'<p class="notice">Não há mudança de uso para este setor. Explore os manejos disponíveis.</p>'}</div><div class="focus-bottom"><span>${state.done?'Manejo encerrado':`${state.actions} ${state.actions===1?'decisão':'decisões'} neste ciclo · ${state.budget} recursos`}</span><button class="text-button" id="back-territory">Voltar ao território</button></div>${!state.done&&!state.actions?'<button class="primary cycle-shortcut" id="focus-advance">Observar o próximo ciclo <span>→</span></button>':''}`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>showPlan(b.dataset.choice));document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{activeGroup=b.dataset.group;showOptions();});document.querySelectorAll('[data-group]').forEach((b,i)=>b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?groups.length-1:(i+(e.key==='ArrowRight'?1:-1)+groups.length)%groups.length;activeGroup=groups[j][0];showOptions();document.querySelector(`[data-group="${activeGroup}"]`).focus();}});$('back-territory').onclick=closeFocus;if($('focus-advance'))$('focus-advance').onclick=()=>{closeFocus();$('advance').click();};}
function interactionNote(a){const t=state.tiles[selected];if(a.id==='notill')return fullSPD(t)?'Os três componentes do sistema já estão presentes.':`Para completar o sistema, combine mínimo revolvimento com ${!t.cover?'cobertura permanente':''}${!t.cover&&!t.cropRotation?' e ':''}${!t.cropRotation?'rotação de culturas':''}.`;if(['microbial','bio_growth'].includes(a.id)&&t.toxic)return 'Há inseticida de amplo espectro ativo. Neste cenário, ele compromete parte da resposta do bioinsumo.';if(a.id==='spray'&&(t.microbial||t.bioGrowth))return 'Há bioinsumos ativos neste setor. O inseticida de amplo espectro pode comprometer parte de sua ação neste cenário.';if(a.id==='fertilizer')return t.cover?'A palhada já protege parte do solo contra o transporte de nutrientes.':'O solo ainda está exposto. A chuva pode transportar parte dos nutrientes até a água.';if(a.id==='drip'&&state.tiles.some((x,i)=>i!==selected&&x.irrigation))return 'Outros setores já retiram água. Esta nova demanda se soma ao uso do recurso compartilhado.';return '';}
function contextual(a){const t=state.tiles[selected],gains=[...a.gains],losses=[...a.losses];if(a.id==='to_crop'||a.id==='to_pasture'){if(t.type==='forest'){gains[1]='Parte da madeira retirada pode abastecer construção, móveis ou reparos uma única vez.';losses[0]='A floresta deixa de oferecer madeira futura, frutos, sementes e parte de seus refúgios.';losses[1]='Menos raízes, copa e serrapilheira mudam a proteção do solo, da água e o microclima.';}else if(t.wood===0){gains.splice(1,1);losses[0]=t.type==='crop'?'A colheita agrícola é substituída por produtos da criação.':'A forragem e a produção animal são substituídas por cultivos.';}}if(a.id==='restore'&&nearWater(state,selected))gains[1]='Nesta margem, a recomposição ajudará a reter sedimentos antes de chegarem à água.';return {gains,losses};}
function showPlan(id){const a=ACTIONS.find(a=>a.id===id),c=contextual(a),available=allowed(state,selected,a),can=available&&state.actions>0&&state.budget>=a.cost,note=interactionNote(a),reason=state.done?'A partida terminou.':!available?'Este manejo já está em uso ou precisa de reposição.':!state.actions?'Para aplicar outro manejo, observe o próximo ciclo.':state.budget<a.cost?'Recursos insuficientes neste ciclo.':'Usa uma decisão deste ciclo.';sectorShell(`<button class="back" id="back-options">← Ver outros manejos</button><div class="eyebrow">PASSO 2 · CONFIRME SUA ESCOLHA</div><h3>${a.name}</h3><p class="plan-summary">${a.summary}</p><div class="tradeoff gain"><h4>O que você ganha</h4><ul>${c.gains.map(g=>`<li>${g}</li>`).join('')}</ul></div><div class="tradeoff care"><h4>O que muda ou exige cuidado</h4><ul>${c.losses.map(l=>`<li>${l}</li>`).join('')}</ul></div>${note?`<div class="interaction-note">${note}</div>`:''}<div class="relation"><span class="eyebrow">RELAÇÃO ECOLÓGICA EM JOGO</span><p>${a.relation}</p></div><div class="confirmation"><button class="primary" id="confirm-plan" ${can?'':'disabled'}>Aplicar este manejo <span>→</span></button><small>${a.cost?`${a.cost} recursos de manejo`:'Sem gasto de recursos'}<br>${reason}</small></div>`);$('back-options').onclick=showOptions;$('confirm-plan').onclick=()=>confirmPlan(a,c);}
function confirmPlan(a,c){const before=structuredClone(state),r=apply(state,selected,a.id);if(!r.ok){toast(r.reason);return;}r.record.gains=c.gains;r.record.losses=c.losses;latestChange={before,after:structuredClone(state),report:impactReport(before,state,selected,a.id),name:a.name};showConnections=false;inspectReady=false;save();render();showChange(latestChange);}
function showChange(change){const {before,after,report,name}=change,t=after.tiles[report.id],[headline,detail]=ACTION_FEEDBACK[report.action]||['Manejo aplicado','Observe as mudanças e seus efeitos.'];$('focus').classList.add('change-mode');$('focus-content').innerHTML=`<section class="change-view"><div class="change-head"><div><span class="eyebrow">PASSO 3 · VEJA A MUDANÇA EM ${idName(report.id)}</span><h2>${headline}</h2><p>${name}</p></div><button class="text-button" id="replay-change">Rever animação</button></div><div class="change-layout"><section class="comparison-panel"><div class="comparison-stage" id="comparison" style="--split:35%"><div class="comparison-before">${sceneHTML(before,report.id)}</div><div class="comparison-after">${sceneHTML(after,report.id,{animate:true})}</div><div class="comparison-divider" aria-hidden="true"><span>↔</span></div><span class="comparison-label before-label">ANTES</span><span class="comparison-label after-label">DEPOIS</span></div><div class="comparison-control"><button class="text-button" id="see-before">Ver antes</button><input id="comparison-slider" type="range" min="0" max="100" value="35" aria-label="Comparar a paisagem antes e depois"><button class="text-button" id="see-after">Ver depois</button></div><div class="scene-callouts">${report.afterScene.labels.slice(-3).map(l=>`<span>${l}</span>`).join('')||'<span>Estrutura da vegetação mantida</span>'}</div><p class="change-explanation">${detail}</p><p class="visual-key">Fotos ilustrativas; linhas e partículas destacam processos simulados.</p></section><section class="impact-panel"><div class="eyebrow">COMO OS SERVIÇOS REAGEM</div>${serviceCards(report)}<p class="impact-reading">Setas indicam a direção da resposta. “Gradual” depende dos ciclos seguintes, mantendo as condições do cenário. Não é pontuação.</p>${report.connections.length?`<details class="connections-preview"><summary>Ver efeitos em outros setores</summary>${report.connections.slice(0,3).map(c=>`<div class="connection-item"><span class="connection-thumb">${sceneHTML(after,c.id,{compact:true})}</span><div><strong>${idName(c.id)} · ${TYPES[after.tiles[c.id].type].name}</strong><small>${c.label}</small></div><span class="connection-arrow ${c.direction}" aria-hidden="true">${c.direction==='up'?'↑':'↓'}</span></div>`).join('')}</details>`:'<div class="local-response">O primeiro efeito está neste setor. Sua resposta continua ligada ao solo, ao clima e à vizinhança.</div>'}<div class="follow-buttons"><button class="primary" id="return-territory">${flowFor(state).canPick?'Escolher a próxima paisagem':'Avançar o ciclo'} <span>→</span></button></div></section></div></section>`;if(!$('focus').open)$('focus').showModal();$('focus').scrollTop=0;const slider=$('comparison-slider'),split=()=>{$('comparison').style.setProperty('--split',slider.value+'%');};slider.oninput=split;$('see-before').onclick=()=>{slider.value=100;split();};$('see-after').onclick=()=>{slider.value=0;split();};$('replay-change').onclick=()=>{slider.value=35;split();$('comparison').classList.remove('replaying');void $('comparison').offsetWidth;$('comparison').classList.add('replaying');};$('return-territory').onclick=()=>{closeFocus();if(flowFor(state).canPick){$('game-main').scrollIntoView({block:'start',behavior:'smooth'});}else{$('advance').click();}};}
function renderTerritoryEffect(){const svg=$('landscape-links'),panel=$('live-effects');if(!latestChange){svg.innerHTML='';panel.hidden=true;return;}const r=latestChange.report,center=id=>({x:(id%3)*200+100,y:Math.floor(id/3)*100+50}),a=center(r.id);svg.innerHTML=showConnections?'<defs><marker id="land-arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0L5 2.5L0 5Z" fill="context-stroke"/></marker></defs>'+r.connections.map(c=>{const b=center(c.id);return `<path class="land-link ${c.direction}" d="M${a.x} ${a.y} Q${(a.x+b.x)/2} ${Math.min(a.y,b.y)-35} ${b.x} ${b.y}" fill="none" stroke-width="2.2" marker-end="url(#land-arrow)"><title>${c.label} · ${idName(c.id)}</title></path><circle class="land-node ${c.direction}" cx="${b.x}" cy="${b.y}" r="6"/>`;}).join('')+`<circle class="land-origin" cx="${a.x}" cy="${a.y}" r="9"/>`:'';panel.hidden=false;panel.innerHTML=`<div class="last-choice-strip"><span>Última escolha: <strong>${latestChange.name}</strong> · ${idName(r.id)}</span><div><button class="text-button" id="review-change">Rever mudança</button>${r.connections.length?`<button class="text-button" id="toggle-connections">${showConnections?'Ocultar conexões':'Ver conexões'}</button>`:''}</div></div>`;$('review-change').onclick=()=>showChange(latestChange);if($('toggle-connections'))$('toggle-connections').onclick=()=>{showConnections=!showConnections;if(showConnections)inspectReady=true;render();};}
function observationFor(id){const p=PRACTICES.find(p=>p.id===id);if(p)return p.observation;return ({keep:'O uso continua, mas o clima, o solo e os outros setores podem mudar o que ele consegue oferecer.',gather:'A colheita passa a oferecer produtos florestais. Parte das sementes continua no ambiente; a retirada moderada reduz um pouco a reposição e a oferta para a fauna.',timber:'O estoque em pé foi reduzido. A madeira retirada pode ser usada agora; novas retiradas precisam esperar a reposição.',to_crop:'A nova produção está em implantação. Refúgios próximos ajudam a polinização; o manejo posterior pode proteger o solo e a água.',to_pasture:'A produção animal depende da recuperação da forragem. O descanso do pasto e a integração de árvores podem mudar sua trajetória.',cover:'O setor destina parte do primeiro ciclo à mudança. A proteção e a decomposição passam a recuperar o solo nos ciclos seguintes.',biocontrol:'As faixas ocupam uma pequena parte da área e favorecem polinizadores e predadores. Observe a resposta durante a pressão de herbivoria.',spray:'A proteção contra herbívoros dura dois ciclos. Os efeitos sobre polinizadores e resíduos também permanecem nesse período.',agro:'A produção começa menor e cresce durante a implantação. As árvores passam a recompor estoque de madeira e habitat.',rotation:'A reorganização reduz temporariamente a produção. O descanso permite recuperação da forragem e melhora gradual do solo.',silvo:'As árvores entram em crescimento e parte do espaço muda de uso. A sombra e os produtos arbóreos se ampliam ao longo dos ciclos.',restore:'A produção agropecuária cede espaço à vegetação em recuperação. As árvores existentes são mantidas; o ganho de cobertura e de estoque é gradual.',rewet:'A produção agropecuária é substituída por água e habitat aquático. A reprodução dos peixes precisará de tempo.',fish:'A retirada aumentou. A reposição do estoque pode não acompanhar a captura; observe a pesca no fim da partida.',nursery:'A captura imediata diminui, enquanto parte dos peixes pode se reproduzir e recompor o estoque.',bank:'A margem passa a reter parte dos sedimentos. A água também continua recebendo efeitos das áreas a montante.',trail:'O acesso cria oportunidades de aprendizagem e renda. A qualidade da experiência continua ligada à água e à paisagem.',sanitation:'O tratamento reduz a carga local sobre a água. Sedimentos e resíduos dos setores produtivos ainda influenciam o rio.',cooperative:'A rede passa a aproveitar melhor os produtos locais. Sem produção suficiente, a organização sozinha não supre as necessidades.',brigade:'A resposta ao incêndio fica organizada. A proteção será percebida no ciclo com fogo extremo.'})[id];}
function intro(){const continuing=state.round>0||state.log.length>0;modal(`<div class="eyebrow">COMO JOGAR</div><h2>Comece pela paisagem.</h2><p>Para professores interessados em serviços ecossistêmicos e no diálogo com seus alunos.</p><div class="steps"><div><strong>1</strong>Clique em uma paisagem.</div><div><strong>2</strong>Escolha e aplique um manejo.</div><div><strong>3</strong>Veja o que mudou e siga o próximo passo.</div></div><p>O jogo indica quando fazer outra escolha e quando avançar o ciclo. A pontuação aparece só no final.</p><details><summary>Regras e sugestões para a aula</summary><p>São seis ciclos e até três manejos por ciclo, conforme os recursos disponíveis. Compare os ganhos e as perdas. Pergunte à turma quem recebe os benefícios e como as escolhas afetam água, solo, organismos e comunidade. O Caderno docente reúne as explicações.</p></details>${continuing?'<p class="opening-save">Sua partida salva será mantida.</p>':''}<button class="primary" id="start">${state.done?'Ver minha partida':continuing?'Continuar minha partida':'Escolher a primeira paisagem'} <span>→</span></button>`);$('start').onclick=()=>{state.started=true;save();closeModal();};}
$('help').onclick=intro;
$('advance').onclick=()=>{if(state.done){finalResult();return;}const r=advance(state);latestChange=null;showConnections=false;inspectReady=false;save();render();if(state.done){finalResult();return;}modal(`<div class="eyebrow">CICLO ${state.round} CONCLUÍDO</div><h2>A paisagem respondeu.</h2><p>${r.notes[0]}</p>${r.notes.length>1?`<details><summary>Ver mais efeitos deste ciclo</summary><ul class="observation-list">${r.notes.slice(1).map(n=>`<li>${n}</li>`).join('')}</ul></details>`:''}<div class="next-cycle-note"><span class="eyebrow">A SEGUIR</span><p>Ciclo ${state.round+1} · ${EVENTS[state.round].season}</p></div><button class="primary" id="next">Escolher uma paisagem no ciclo ${state.round+1} <span>→</span></button>`);$('next').onclick=()=>{closeModal();$('game-main').scrollIntoView({block:'start',behavior:'smooth'});};};
function finalResult(){const m=metrics(state),baseline=metrics(initial()),n=score(state),avg=k=>state.history.reduce((a,h)=>a+h[k],0)/state.history.length;const services=[['Provisão','food','Alimentos, pesca e produtos obtidos.'],['Regulação','regulation','Água, retenção e estoque arbóreo.'],['Suporte','support','Solo, habitat e processos associados.'],['Culturais','cultural','Aprendizagem, identidade e visitação.']];const logging=state.log.filter(l=>l.action!=='keep');const conversion=state.log.filter(l=>l.oldType==='forest'&&['to_crop','to_pasture'].includes(l.action));modal(`<div class="eyebrow">AGORA, O BALANÇO FINAL</div><h2>O que seu manejo deixou?</h2><div class="score-line"><strong>${n}</strong><small>/ 100<br>equilíbrio do manejo</small></div><p>Esta pontuação resume a capacidade de produzir, manter a água e sustentar outros benefícios ao longo da partida. Os valores abaixo são índices didáticos, sem unidade física ou monetária.</p><div class="final-services">${services.map(([name,k,desc])=>`<div><strong>${round(m[k])}<small style="display:inline;font-size:10px"> /100</small></strong><span>${name}</span><small>${desc}</small></div>`).join('')}</div><h3>Produtos e processos: o que mudou</h3><div class="table-wrap"><table><thead><tr><th>O que a comunidade recebe ou mantém</th><th>Início</th><th>Final / trajetória</th></tr></thead><tbody><tr><td>Produção de alimentos por ciclo, incluindo pesca e coleta</td><td>${baseline.foodUnits.toFixed(1).replace('.',',')} un.</td><td>${m.foodUnits.toFixed(1).replace('.',',')} un. no final</td></tr><tr><td>Madeira mantida em pé, disponível para usos futuros</td><td>${round(baseline.woodStock)} un.</td><td>${round(m.woodStock)} un.</td></tr><tr><td>Madeira retirada e aproveitada na partida</td><td>—</td><td>${round(state.timberHarvest)} un.; ${round(state.conversionWood)} vieram de conversões</td></tr><tr><td>Produtos alimentares da floresta e das árvores</td><td>${baseline.forestFood.toFixed(1).replace('.',',')} un./ciclo</td><td>${m.forestFood.toFixed(1).replace('.',',')} un./ciclo</td></tr><tr><td>Condição do estoque pesqueiro</td><td>${round(baseline.fishStock)}/100</td><td>${round(m.fishStock)}/100</td></tr><tr><td>Qualidade da água da comunidade</td><td>${round(baseline.water)}/100</td><td>${round(m.water)}/100</td></tr><tr><td>Disponibilidade compartilhada de água</td><td>${round(baseline.waterAvailability)}/100</td><td>${round(m.waterAvailability)}/100</td></tr><tr><td>Condição média do solo</td><td>${round(baseline.soil)}/100</td><td>${round(m.soil)}/100</td></tr></tbody></table></div><p class="notice">${conversion.length?`Você converteu ${conversion.length} setor(es) de floresta: obteve madeira uma vez e abriu espaço para nova produção; os produtos florestais futuros desses setores foram substituídos. `:''}${logging.length} intervenções alteraram o território. Ganhos e perdas também dependeram do clima, da vizinhança e do tempo de implantação. As unidades de produção são fictícias e servem apenas à comparação dentro do jogo.</p><details><summary>Como a pontuação foi calculada</summary><p>25% da provisão média + 25% da qualidade média da água + 20% do suporte final + 15% dos serviços culturais finais + 15% das oportunidades médias de renda. Os pesos são uma escolha pedagógica. Não há desconto de pontos associado ao nome de um uso da terra.</p><p>Provisão média: ${round(avg('food'))}; água média: ${round(avg('water'))}; suporte final: ${round(m.support)}; culturais finais: ${round(m.cultural)}; renda média: ${round(avg('livelihood'))}. Os serviços intermediários não são valores econômicos somáveis.</p></details><button class="primary" id="final-log">Rever as decisões e suas trocas <span>→</span></button><button class="text-button" id="final-map" style="display:block;margin:15px auto 0">Voltar ao território</button>`,true);$('final-log').onclick=showLog;$('final-map').onclick=closeModal;}
function showLog(){modal(`<div class="eyebrow">MEMÓRIA DAS DECISÕES</div><h2>O que foi escolhido e o que mudou.</h2>${state.log.length?state.log.map(l=>`<div class="log-entry"><small>Ciclo ${l.round} · setor ${idName(l.tile)}</small><strong>${l.name}</strong><p><b>Ganho ou uso mantido:</b> ${l.gains[0]}</p><p><b>Troca ou cuidado:</b> ${l.losses[0]}</p></div>`).join(''):'<p>Ainda não há decisões registradas. Você pode abrir um setor e escolher um manejo ou observar um ciclo sem intervir.</p>'}<button class="primary" id="log-close">Voltar à paisagem <span>→</span></button>`);$('log-close').onclick=closeModal;}
$('show-log').onclick=showLog;
$('teacher').onclick=()=>{modal(`<div class="eyebrow">SERVIÇOS ECOSSISTÊMICOS · CADERNO DOCENTE</div><h2>Manejar é decidir entre usos e tempos.</h2><p><b>Público-alvo:</b> professores interessados em serviços ecossistêmicos e em como dialogar com seus alunos sobre as escolhas de manejo, seus benefícios e suas consequências. O jogo pode apoiar a mediação docente e a comparação de estratégias em pequenos grupos. Sugestão: 15–20 minutos de partida e discussão após o balanço.</p><h3>O que os estudantes precisam acompanhar</h3><p>Quais produtos surgiram? Quais deixaram de ser obtidos? O benefício é imediato ou recorrente? Quem o recebe? A produção de um setor depende de quais relações nos setores vizinhos?</p><div class="table-wrap"><table><tr><th>Relação / processo</th><th>Onde aparece na mecânica</th></tr><tr><td>Mutualismo</td><td>Refúgios e faixas floridas favorecem polinizadores e a produção de abóbora.</td></tr><tr><td>Predação e herbivoria</td><td>Predadores reduzem perdas nos cultivos. O pastejo depende do equilíbrio entre consumo e recuperação da forragem.</td></tr><tr><td>Decomposição</td><td>Resíduos e cobertura orgânica melhoram gradualmente a condição do solo.</td></tr><tr><td>Competição</td><td>Árvores, cultivos e forragem compartilham recursos. Sistemas com árvores têm custos de implantação e reorganização da área produtiva.</td></tr><tr><td>Reposição de estoques</td><td>Madeira e peixes podem ser utilizados agora ou mantidos para usos futuros. Retirada e reposição seguem ritmos diferentes.</td></tr></table></div><h3>Mais caminhos na agricultura</h3><p>Solo e água: cobertura, plantio direto, rotação de culturas, composto orgânico, adubação mineral e gotejamento. Vida e controle: faixas floridas, bioinsumo para crescimento, bioinseticida microbiano, manejo integrado de pragas e inseticida de amplo espectro.</p><p>O sistema de plantio direto combina mínimo revolvimento, cobertura permanente e rotação. Bioinsumos são diversos: o agente de crescimento representado não tem a mesma função do bioinseticida. A compatibilidade com o inseticida no jogo é uma hipótese de cenário, não uma generalização sobre todos os produtos.</p><p>O bioinsumo para crescimento dura três ciclos; bioinseticida, adubação mineral e inseticida duram dois, incluindo a aplicação. A resposta ao surto no manejo integrado usa um limiar didático de perda potencial, sem valor como recomendação de campo. O gotejamento reduz o estresse local, mas retira água do recurso compartilhado.</p><h3>Para comparar em sala</h3><p>Peça a um grupo que combine cobertura, plantio direto e rotação. Outro pode priorizar fertilidade e bioinsumos; outro, controle rápido das pragas. Cada grupo deve explicar tanto as respostas produtivas quanto os custos, as interações e os efeitos sobre os outros setores.</p><h3>Os quatro tipos de serviços, em conjunto</h3><p>Provisão: alimentos, pescado, madeira e produtos florestais. Regulação: água, erosão, retenção de fluxos e carbono. Suporte: solo, habitat e processos que sustentam outros benefícios. Culturais: aprendizagem, identidade, visitação e relação com o lugar. A classificação segue a Avaliação Ecossistêmica do Milênio; suporte não é tratado como benefício econômico adicional.</p><h3>Leia a resposta visual</h3><p>Depois de aplicar um manejo, compare as imagens antes e depois com o controle deslizante. Palhada, faixas floridas, linhas de irrigação, piquetes, trilhas e vegetação jovem permanecem visíveis na paisagem. Linhas e partículas são camadas explicativas dos processos, não fotografias desses organismos em escala real.</p><p>As setas dos serviços comparam o cenário antes e depois da última intervenção sob as mesmas condições. A resposta gradual compara até dois avanços sem novos manejos. As conexões com outros setores seguem a vizinhança de polinizadores ou o recurso hídrico compartilhado do modelo. Crescimento vegetal, recuperação de estoques e sucessão não são instantâneos. A pontuação permanece apenas no fim.</p><h3>Regras e limites do modelo</h3><p>São nove setores, seis ciclos e três decisões por ciclo. A tela mostra um próximo passo por vez. Com escolhas disponíveis, selecione uma paisagem; quando o trabalho ou os recursos terminam, avance o ciclo. O menu Registros e ferramentas permite encerrar o ciclo antes de usar todas as escolhas. As conexões e os efeitos detalhados ficam disponíveis sob demanda. A influência espacial considera setores com lados em comum. A escolha de manejo altera produção, cobertura, pressão sobre estoques e exposição aos eventos; os índices são revelados somente no final. Inseticida dura dois ciclos, contando a aplicação. A retirada seletiva de madeira exige intervalo de três ciclos. A implantação dos sistemas com árvores é gradual.</p><p class="notice">Custos, pesos, limiares e quantidades são convenções didáticas sem calibração empírica. Os ciclos não correspondem a anos e não representam a idade de uma floresta real. O cenário de incêndio não abrange todos os papéis do fogo no Cerrado. O jogo não avalia a autorização legal de conversões ou extração de madeira. O mapa é fictício, as imagens são sintéticas e a partida fica neste navegador.</p><div class="source-links"><a target="_blank" rel="noopener" href="https://www.embrapa.br/en/web/agencia-de-informacao-tecnologica/tematicas/sistema-plantio-direto/fundamentos/conceitos/sistema-plantio-direto-spd-">Embrapa · plantio direto</a><a target="_blank" rel="noopener" href="https://www.embrapa.br/pt/portfolio/insumos-biologicos">Embrapa · bioinsumos</a><a target="_blank" rel="noopener" href="https://www.millenniumassessment.org/documents/document.356.aspx.pdf">Avaliação do Milênio</a><a target="_blank" rel="noopener" href="https://www.fao.org/forestry/sfm/overview/">FAO · manejo florestal</a><a target="_blank" rel="noopener" href="https://www.fao.org/sustainable-forest-management-toolbox/modules/agroforestry/2/en">FAO · agroflorestas</a><a target="_blank" rel="noopener" href="https://www.embrapa.br/en/web/florestas/ilpf">Embrapa · sistemas integrados</a></div><button class="primary" id="teacher-close">Voltar ao jogo <span>→</span></button>`);$('teacher-close').onclick=closeModal;};
$('restart').onclick=()=>{modal('<div class="eyebrow">EXPERIMENTAR OUTRA ESTRATÉGIA</div><h2>Começar uma nova partida?</h2><p>Você pode exportar a partida atual antes de substituí-la.</p><button class="primary" id="confirm-restart">Começar do primeiro ciclo <span>→</span></button><button class="text-button" id="cancel-restart" style="display:block;margin:15px auto 0">Continuar a partida atual</button>');$('confirm-restart').onclick=()=>{state=initial();state.started=true;latestChange=null;showConnections=false;inspectReady=false;save();render();closeModal();};$('cancel-restart').onclick=closeModal;};
$('export').onclick=()=>{const data={jogo:'Paisagem Viva · Manejo, perdas e ganhos',publico:'Professores interessados em serviços ecossistêmicos e no diálogo com os alunos',exportadoEm:new Date().toISOString(),modelo:'Didático, sem calibração ou valor preditivo',estado:state,...(state.done?{balanco:metrics(state),pontuacao:score(state)}:{})},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='paisagem-viva-manejo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Registro exportado.');};
render();intro();
